def min_hours_to_build_houses(n, heights):
    import math

    def can_build(k):
        count = 0
        last_height = float('-inf')
        for i in range(n):
            if heights[i] > last_height:
                count += 1
                last_height = heights[i]
            if count >= k:
                return True
        return False

    max_k = math.ceil(n / 2)
    results = []

    for k in range(1, max_k + 1):
        left, right = 0, 10**9
        while left < right:
            mid = (left + right) // 2
            adjusted_heights = [h - mid for h in heights]
            if can_build(k):
                right = mid
            else:
                left = mid + 1
        results.append(left)

    return results

if __name__ == "__main__":
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    heights = list(map(int, data[1:n+1]))

    result = min_hours_to_build_houses(n, heights)
